struct Query {
    int l, r, id;
} q[N];

int block;

bool cmp(Query a, Query b) {
    if (a.l / block != b.l / block)
        return a.l / block < b.l / block;
    return a.r < b.r;
}

void add(int pos) {
    cnt[a[pos]]++;
    if (cnt[a[pos]] == 1) cur++;
}

void remove(int pos) {
    cnt[a[pos]]--;
    if (cnt[a[pos]] == 0) cur--;
}

